"use client";
import * as React from "react";
import { Icon } from "@/registry/p1/internal/icons";
import { RichValue } from "@/registry/p1/internal/rich";
import "./accordion.css";

export interface AccordionItem {
  title: string;
  body: string;
}

export interface AccordionProps {
  heading: string;
  align: "left" | "center";
  items: AccordionItem[];
}

export function AccordionRender({ heading, align, items }: AccordionProps) {
  const list = items || [];
  const [open, setOpen] = React.useState<Record<string, boolean>>(
    list[0] ? { [list[0].title || "0"]: true } : {},
  );
  return (
    <div className="p1-accordion p1-block" data-align={align}>
      {heading && <h2 className="p1-accordion__heading">{heading}</h2>}
      <div className="p1-accordion__list">
        {list.map((it, ii) => {
          const key = it.title || String(ii);
          const isOpen = !!open[key];
          return (
            <div key={key} className="p1-accordion__item" data-open={isOpen ? "true" : undefined}>
              <button
                type="button"
                onClick={() => setOpen((o) => ({ ...o, [key]: !o[key] }))}
                className="p1-accordion__trigger"
              >
                <span className="p1-accordion__title">{it.title || `Item ${ii + 1}`}</span>
                <Icon name="plus" className="p1-accordion__icon" />
              </button>
              {isOpen && (
                <div className="p1-accordion__body">
                  <RichValue value={it.body || ""} />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { AccordionRender, type AccordionProps, type AccordionItem } from "./accordion";
export type { AccordionProps, AccordionItem };

export const AccordionBlock: ComponentConfig<AccordionProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A section heading of 2–6 words. Plain text, sentence case, no trailing punctuation." },
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
    items: {
      type: "array" as const,
      arrayFields: {
        title: { type: "text" as const, contentEditable: true, visible: false },
        body: { type: "richtext" as const, contentEditable: true },
      },
      defaultItemProps: { title: "Section title", body: "<p>Section content.</p>" },
      getItemSummary: (item: AccordionItem) => item.title || "Section",
    },
  },
  defaultProps: {
    heading: "The details",
    align: "left",
    items: [
      {
        title: "What frameworks are supported?",
        body: "<p>WordPress, Drupal, and Next.js — all on the same platform, with the same <mark>Dev-Test-Live</mark> workflow.</p>",
      },
      {
        title: "How do environments work?",
        body: "<p>Every site gets Dev, Test, and Live — plus unlimited Multidev branches for parallel work.</p><ul><li>Isolated by default</li><li>Shareable preview URLs</li><li>One-click promotion</li></ul>",
      },
      {
        title: "Can the whole team use it?",
        body: "<p>Yes. Developers, marketers, and IT share one workflow with role-based access — no one waits on anyone else.</p>",
      },
    ],
  },
  render: AccordionRender,
};

export const meta = defineMeta({
  title: 'Accordion',
  description: 'Expandable list of title/body items with a section heading; use for collapsible content like FAQs or grouped details.',
  categories: ["layout"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons","@p1/internal-rich"],
});

.p1-accordion {
  margin-inline: auto;
  max-inline-size: var(--p1-container-narrow);
}

.p1-accordion__heading {
  font-family: var(--p1-font-heading);
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-accordion__heading { font-size: var(--p1-text-3xl); }
}
.p1-accordion[data-align="center"] .p1-accordion__heading { text-align: center; }

.p1-accordion__list { border-block-start: 1px solid var(--p1-border); }

.p1-accordion__item { border-block-end: 1px solid var(--p1-border); }

.p1-accordion__trigger {
  align-items: center;
  background: none;
  border: 0;
  cursor: pointer;
  display: flex;
  gap: var(--p1-space-md);
  justify-content: space-between;
  padding-block: var(--p1-space-md);
  text-align: start;
  width: 100%;
}

.p1-accordion__title {
  color: var(--p1-fg-default);
  font-size: var(--p1-text-lg);
  font-weight: var(--p1-weight-bold);
  line-height: var(--p1-leading-tight);
}

.p1-accordion__icon {
  block-size: 1.25rem;
  color: var(--p1-fg-muted);
  flex: none;
  inline-size: 1.25rem;
}
@media (prefers-reduced-motion: no-preference) {
  .p1-accordion__icon { transition: transform 200ms ease; }
}
.p1-accordion__item[data-open="true"] .p1-accordion__icon {
  transform: rotate(45deg);
}

.p1-accordion__body { padding-block-end: var(--p1-space-lg); }

